CREATE TABLE "caixa_movimentos" ("id" TEXT NOT NULL, "caixa_sessao_id" TEXT NOT NULL, "tipo" TEXT NOT NULL, "valor" REAL NOT NULL, "descricao" TEXT NOT NULL, "ticket_id" TEXT NULL, "forma_pagamento" TEXT NULL, "criado_em" INTEGER NOT NULL, "sync_status" TEXT NOT NULL DEFAULT 'pendente', PRIMARY KEY ("id"));
CREATE TABLE "caixa_sessoes" ("id" TEXT NOT NULL, "operacao_id" TEXT NOT NULL, "operador_id" TEXT NOT NULL, "operador_nome" TEXT NOT NULL, "fundo_caixa" REAL NOT NULL, "total_entradas" REAL NOT NULL DEFAULT 0.0, "total_sangrias" REAL NOT NULL DEFAULT 0.0, "total_fechamento" REAL NULL, "status" TEXT NOT NULL DEFAULT 'aberta', "abertura_epoch" INTEGER NOT NULL, "fechamento_epoch" INTEGER NULL, "observacao_fechamento" TEXT NULL, "sync_status" TEXT NOT NULL DEFAULT 'pendente', PRIMARY KEY ("id"));
CREATE TABLE "liberacoes_cache" ("ticket_id" TEXT NOT NULL, "operacao_id" TEXT NOT NULL, "parceiro_nome" TEXT NOT NULL, "regra_nome" TEXT NOT NULL, "abater_minutos" INTEGER NOT NULL DEFAULT 0, "desconto_percentual" INTEGER NOT NULL DEFAULT 0, "desconto_valor" REAL NOT NULL DEFAULT 0.0, "liberado_em_epoch" INTEGER NOT NULL, PRIMARY KEY ("ticket_id"));
CREATE TABLE "mensalidade_pagamentos" ("id" TEXT NOT NULL, "operacao_id" TEXT NOT NULL, "cliente_id" TEXT NOT NULL, "cliente_nome" TEXT NOT NULL, "plano_id" TEXT NULL, "competencia" TEXT NOT NULL, "valor" REAL NOT NULL, "forma_pagamento" TEXT NULL, "pago_em_epoch" INTEGER NOT NULL, "origem" TEXT NOT NULL DEFAULT 'app', "registrado_por" TEXT NULL, "caixa_sessao_id" TEXT NULL, "caixa_movimento_id" TEXT NULL, "observacao" TEXT NULL, "sync_status" TEXT NOT NULL DEFAULT 'pendente', "criado_em" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "operacao_cache" ("operacao_id" TEXT NOT NULL, "nome" TEXT NOT NULL, "codigo" TEXT NOT NULL, "qtd_vagas" INTEGER NOT NULL, "config_json" TEXT NOT NULL, "sincronizado_em" INTEGER NOT NULL, PRIMARY KEY ("operacao_id"));
CREATE TABLE "patio_cliente_placas" ("operacao_id" TEXT NOT NULL, "placa" TEXT NOT NULL, "cliente_id" TEXT NOT NULL, "descricao" TEXT NULL, PRIMARY KEY ("operacao_id", "placa"));
CREATE TABLE "patio_clientes" ("id" TEXT NOT NULL, "operacao_id" TEXT NOT NULL, "nome" TEXT NOT NULL, "plano_id" TEXT NULL, "plano_nome" TEXT NULL, "plano_tipo" TEXT NULL, "plano_valor" REAL NULL, "vagas" INTEGER NOT NULL DEFAULT 1, "vencimento_epoch" INTEGER NULL, "dia_vencimento" INTEGER NULL, "bloqueado" INTEGER NOT NULL DEFAULT 0 CHECK ("bloqueado" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "sync_log" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "entidade" TEXT NOT NULL, "entidade_id" TEXT NOT NULL, "operacao" TEXT NOT NULL, "payload" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'pendente', "tentativas" INTEGER NOT NULL DEFAULT 0, "proxima_tentativa_epoch" INTEGER NULL, "erro_ultima_tentativa" TEXT NULL, "criado_em" INTEGER NOT NULL);
CREATE TABLE "tarifas" ("id" TEXT NOT NULL, "operacao_id" TEXT NOT NULL, "nome" TEXT NOT NULL DEFAULT 'Padrão', "tipo_veiculo" TEXT NOT NULL, "ordem" INTEGER NOT NULL DEFAULT 0, "visivel_operador" INTEGER NOT NULL DEFAULT 1 CHECK ("visivel_operador" IN (0, 1)), "fracao_inicial_minutos" INTEGER NOT NULL, "fracao_inicial_valor" REAL NOT NULL, "fracao_adicional_minutos" INTEGER NOT NULL, "fracao_adicional_valor" REAL NOT NULL, "teto_diaria" REAL NOT NULL, "tolerancia_minutos" INTEGER NOT NULL, "pernoite_valor" REAL NOT NULL, "pernoite_hora_inicio" INTEGER NOT NULL, "pernoite_hora_fim" INTEGER NOT NULL, "vigencia_inicio_epoch" INTEGER NOT NULL, "vigencia_fim_epoch" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "tickets" ("id" TEXT NOT NULL, "operacao_id" TEXT NOT NULL, "placa" TEXT NOT NULL, "tipo_veiculo" TEXT NOT NULL, "entrada_epoch" INTEGER NOT NULL, "saida_epoch" INTEGER NULL, "valor_calculado" REAL NULL, "valor_cobrado" REAL NULL, "forma_pagamento" TEXT NULL, "motivo_isencao" TEXT NULL, "status" TEXT NOT NULL DEFAULT 'aberto', "operador_id" TEXT NOT NULL, "caixa_sessao_id" TEXT NULL, "tabela_preco_id" TEXT NULL, "cliente_id" TEXT NULL, "plano_id" TEXT NULL, "origem" TEXT NOT NULL DEFAULT 'avulso', "atk" TEXT NULL, "itk" TEXT NULL, "authorization_code" TEXT NULL, "brand" TEXT NULL, "card_pan" TEXT NULL, "installments" INTEGER NULL, "payment_processor" TEXT NULL, "foto_entrada_path" TEXT NULL, "foto_entrada_enviada" INTEGER NOT NULL DEFAULT 0 CHECK ("foto_entrada_enviada" IN (0, 1)), "sync_status" TEXT NOT NULL DEFAULT 'pendente', "criado_em" INTEGER NOT NULL, "atualizado_em" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE INDEX idx_menspag_cliente ON mensalidade_pagamentos(cliente_id, competencia);
CREATE INDEX idx_menspag_sync ON mensalidade_pagamentos(sync_status);
CREATE INDEX idx_synclog_status_prox ON sync_log(status, proxima_tentativa_epoch);
CREATE INDEX idx_tickets_op_placa_status ON tickets(operacao_id, placa, status);
CREATE INDEX idx_tickets_op_status ON tickets(operacao_id, status);
CREATE INDEX idx_tickets_sync_status ON tickets(sync_status);
